});

test('invoiceTotals with discounts', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, discountPercent: 10 }, // 100.00 - 10.00 = 90.00
      { qty: 1, unitPrice: 20000, discountPercent: 50 }, // 200.00 - 100.00 = 100.00
    ],
  };

