    });
    assert.equal(result.ok, false, `discount ${discount} should be invalid`);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  }
});

test('createInvoice accepts valid discount percentages including decimals', () => {
  const validDiscounts = [0, 0.5, 12.5, 50, 99.99, 100];

  for (const discount of validDiscounts) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-01-15',
      lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: discount }],
    });
    assert.equal(result.ok, true, `discount ${discount} should be valid`);
    assert.equal(result.value.lines[0].discountPercent, discount);
  }
});

test('lineDiscount calculates discount amount correctly', () => {
  // 10% of €95.00 = €9.50
  assert.equal(lineDiscount({ qty: 1, unitPrice: 9500, discountPercent: 10 }), 950);
  // 50% of €120.00 = €60.00
  assert.equal(lineDiscount({ qty: 1, unitPrice: 120000, discountPercent: 50 }), 60000);
  // 12.5% of €95.00 * 5 = €59.38
  assert.equal(lineDiscount({ qty: 5, unitPrice: 9500, discountPercent: 12.5 }), 5938);
});

test('lineDiscount returns 0 if no discount', () => {
  assert.equal(lineDiscount({ qty: 1, unitPrice: 9500 }), 0);
  assert.equal(lineDiscount({ qty: 1, unitPrice: 9500, discountPercent: undefined }), 0);
});

test('lineDiscount never returns negative values', () => {
  // Even with 100% discount on very small amounts
  assert.equal(lineDiscount({ qty: 0, unitPrice: 9500, discountPercent: 100 }), 0);
});

test('invoiceTotals with discounts', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, discountPercent: 10 }, // 100.00 - 10.00 = 90.00
      { qty: 1, unitPrice: 20000, discountPercent: 50 }, // 200.00 - 100.00 = 100.00
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 30000); // 100 + 200
  assert.equal(totals.discount, 11000); // 10 + 100
  assert.equal(totals.total, 19000); // 30 - 11
});

test('invoiceTotals with no discounts', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000 },
      { qty: 1, unitPrice: 20000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 30000);
});

test('invoiceTotals never returns negative total', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 100 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.total, 0);
});

test('addLine accepts discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines[1].discountPercent, 15);
});

test('addLine fails with DISCOUNT_INVALID for invalid discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 150 });

  assert.equal(addResult.ok, false);
  assert.equal(addResult.error, 'DISCOUNT_INVALID');
});

test('addLine updates discount when adding to existing SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 20 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines[0].qty, 8);
  assert.equal(addResult.value.lines[0].discountPercent, 20);
});

